<?php $item = $page->post; $isPage = $item->isPage; $sideToc = !$isPage && $item->toc !== ''; // Without the side table of contents, the text uses the full width. ?>
<div class="<?= $isPage ? '' : 'h-entry ' ?>mx-auto flex max-w-[1120px] flex-col gap-6 px-4 py-5 md:gap-10 md:px-6 md:py-12">
<?php $otherTranslations = array_values(array_filter($item->translations, fn ($t) => !$t->current)); if ($otherTranslations):
// Up to three languages are buttons; with more, two buttons and a menu with the rest.
$shown = count($otherTranslations) > 3 ? array_slice($otherTranslations, 0, 2) : $otherTranslations; $hidden = array_slice($otherTranslations, count($shown));
$choice = 'inline-flex min-h-11 w-full items-center justify-center gap-2 whitespace-nowrap rounded-lg border border-orange-300 bg-white px-4 font-semibold text-orange-900 dark:border-orange-800 dark:bg-transparent dark:text-orange-300'; ?>
<div class="flex flex-col gap-3 rounded-xl border border-orange-200 bg-orange-50 p-3.5 md:flex-row md:items-center md:justify-between md:px-6 md:py-4 dark:border-orange-900 dark:bg-orange-950/40">
<p class="text-sm text-orange-900 md:text-base dark:text-orange-200"><?= e(t('available_translations')) ?></p><nav class="flex flex-wrap gap-2" aria-label="<?= e(t('translation')) ?>"><?php foreach ($shown as $translation): ?><a class="<?= $choice ?> flex-1" lang="<?= e($translation->code) ?>" href="<?= e($translation->url) ?>"><?= e($translation->nativeName) ?></a><?php endforeach ?>
<?php if ($hidden): ?><details class="relative flex-1"><summary class="<?= $choice ?> cursor-pointer list-none [&::-webkit-details-marker]:hidden"><?= e(t('more_languages', ['count' => count($hidden)])) ?><svg width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M2 3.5 5 6.5 8 3.5" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></summary>
<ul class="absolute end-0 z-20 mt-2 max-h-[60vh] w-60 overflow-y-auto rounded-xl border border-slate-200 bg-white p-2 shadow-lg dark:border-slate-700 dark:bg-slate-900"><?php foreach ($hidden as $translation): ?><li><a class="flex min-h-11 items-center justify-between gap-3 rounded-lg px-3 text-sm hover:bg-slate-100 dark:hover:bg-slate-800" href="<?= e($translation->url) ?>"><span lang="<?= e($translation->code) ?>" dir="<?= e($translation->dir) ?>"><?= e($translation->nativeName) ?></span><span class="font-mono text-xs text-slate-600 dark:text-slate-400"><?= e($translation->code) ?></span></a></li><?php endforeach ?></ul></details><?php endif ?></nav></div><?php endif ?>
<header class="flex max-w-[820px] flex-col gap-4 md:gap-5">
<nav aria-label="<?= e(t('breadcrumb')) ?>" class="hidden items-center gap-2 text-sm text-slate-600 md:flex dark:text-slate-400"><a class="inline-flex min-h-11 min-w-11 items-center" href="<?= e($isPage ? $site->homeUrl : $site->postsUrl) ?>"><?= e(t($isPage ? 'home' : 'posts')) ?></a><?php if ($item->category): ?><span>/</span><a class="inline-flex min-h-11 min-w-11 items-center" href="<?= e($item->category->url) ?>"><?= e($item->category->name) ?></a><?php endif ?></nav>
<?php if (!$isPage): ?><p class="order-first font-mono text-xs text-slate-600 md:order-none md:hidden dark:text-slate-400"><?= e($item->published->long) ?> · <?= e(t('reading_minutes', ['minutes' => $item->readingMinutes])) ?></p><?php endif ?>
<h1 class="p-name text-[32px] leading-tight font-bold tracking-tight md:text-[64px] md:leading-[1.04] md:tracking-[-.035em]"><?= e($item->title) ?></h1><?php if (!$isPage): ?><data class="u-url" value="<?= e(absolute_url($item->url)) ?>"></data><?php endif ?>
<p class="p-summary hidden font-serif text-[22px] leading-normal text-slate-700 md:block dark:text-slate-300"><?= e($item->summary) ?></p>
<?php if (!$isPage): ?><div class="hidden flex-wrap items-center gap-x-5 gap-y-2 font-mono text-xs text-slate-600 md:flex dark:text-slate-400"><span><?= e(t('published')) ?> <time class="dt-published" datetime="<?= e($item->published->iso) ?>"><?= e($item->published->long) ?></time></span><span><?= e(t('reading_minutes', ['minutes' => $item->readingMinutes])) ?></span><div class="flex flex-wrap gap-1.5"><?php foreach ($item->tags as $tag): ?><a class="p-category tag" href="<?= e($tag->url) ?>">#<?= e($tag->name) ?></a><?php endforeach ?></div></div><?php endif ?>
</header>
<?php if (!$isPage && $item->cover !== null): ?><figure class="h-[220px] overflow-hidden rounded-2xl md:h-[380px]"><?= partial('cover', ['post' => $item]) ?></figure><?php endif ?>
<?php if (!$isPage && $item->toc !== ''): ?><details class="rounded-xl border border-slate-200 bg-white md:hidden dark:border-slate-800 dark:bg-slate-900"><summary class="flex min-h-12 cursor-pointer items-center justify-between px-4 font-semibold"><?= e(t('on_this_page')) ?><span aria-hidden="true">⌄</span></summary><div class="toc-meteor p-3"><?= $item->toc ?></div></details><?php endif ?>
<?= slot('post_before') ?><div class="flex items-start gap-14"><article class="e-content prose-meteor min-w-0 flex-1<?= $sideToc ? ' md:flex-[0_1_700px]' : '' ?>"><?= $item->html ?></article>
<?php if ($sideToc): ?><aside aria-labelledby="toc-title" class="sticky top-6 hidden min-w-60 flex-[1_1_240px] rounded-[14px] border border-slate-200 bg-white p-6 md:block dark:border-slate-800 dark:bg-slate-900"><h2 id="toc-title" class="eyebrow mb-3"><?= e(t('on_this_page')) ?></h2><div class="toc-meteor"><?= $item->toc ?></div><?php if ($item->category): ?><div class="mt-4 border-t border-slate-200 pt-3 dark:border-slate-800"><p class="text-sm text-slate-600 dark:text-slate-400"><?= e(t('category')) ?></p><a class="accent inline-flex min-h-11 items-center font-semibold" href="<?= e($item->category->url) ?>"><?= e($item->category->name) ?></a></div><?php endif ?></aside><?php endif ?></div>
<?= slot('post_after') ?><?php if (!$isPage): $authorCard = $site->author !== null && $site->postAuthorCard; ?>
<?php if ($item->tags || $authorCard): // Tags (on small screens) and the author card, below a line like the one above Previous/Next. ?>
<div class="<?= $authorCard ? 'flex' : 'flex md:hidden' ?> flex-col gap-6 border-t border-slate-200 pt-6 dark:border-slate-800">
<?php if ($item->tags): ?><div class="flex flex-wrap gap-2 md:hidden"><?php foreach ($item->tags as $tag): ?><a class="tag" href="<?= e($tag->url) ?>">#<?= e($tag->name) ?></a><?php endforeach ?></div><?php endif ?>
<?php if ($authorCard): ?><section aria-labelledby="author-heading" class="max-w-[700px]"><h2 id="author-heading" class="eyebrow mb-4"><?= e(t('about_author')) ?></h2><div class="rounded-2xl border border-slate-200 bg-white p-5 md:p-7 dark:border-slate-800 dark:bg-slate-900"><?= partial('author-card', ['author' => $site->author, 'variant' => 'post']) ?></div></section><?php endif ?>
</div>
<?php endif ?>
<?php if ($page->comments) { echo partial('comments'); } ?>
<?php if (array_filter($page->neighbors)): ?><nav aria-label="<?= e(t('more_posts')) ?>" class="grid gap-4 border-t border-slate-200 pt-6 md:grid-cols-2 dark:border-slate-800"><?php foreach ($page->neighbors as $rel => $neighbor): if (!$neighbor) { continue; } ?><a class="flex flex-col gap-2 rounded-[14px] border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900" rel="<?= e($rel) ?>" href="<?= e($neighbor->url) ?>"><span class="eyebrow"><?= e(t($rel === 'prev' ? 'previous' : 'next')) ?></span><span class="text-xl font-semibold"><?= e($neighbor->title) ?></span></a><?php endforeach ?></nav><?php endif ?>
<?php endif ?>
</div>
